package io.knowledgebrain.learning;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;
import io.knowledgebrain.contracts.learning.roadmaprating.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP",matches=".+")
class RoadmapRatingKafkaIntegrationTest {
 @Test void ratingRevisionsReachKafkaWithExactBytesOrderAndPinnedVersion()throws Exception{
  var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var canonical=new PublicRoadmapStore(ds,Clock.systemUTC());var store=new RoadmapRatingStore(ds,canonical,Clock.systemUTC());var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();var author=ids.next();String trace="e".repeat(32);var proposal=canonical.submit(space,author,null,0,"Kafka rating","","Explicit",PublicRoadmapStoreIntegrationTest.graph(),trace);canonical.review(space,proposal.contributionId(),actor,1,"APPROVED","Checked",trace);canonical.merge(space,proposal.contributionId(),actor,2,trace);var first=store.change(space,proposal.roadmapId(),actor,0,1,4,false,trace).rating();store.change(space,proposal.roadmapId(),actor,1,1,5,false,trace);store.change(space,proposal.roadmapId(),actor,2,0,0,true,trace);store.change(space,proposal.roadmapId(),actor,3,1,2,false,trace);var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid=?",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),first.ratingId()).forEach(v->expected.put(v.getKey(),v.getValue()));assertEquals(4,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP"));options.put("group.id","learning-validation-"+ids.next());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/learning-kafka-test/ca.crt")));options.put("ssl.keystore.type","PEM");options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/learning-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/learning-kafka-test/user.key")));

  try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("learning.roadmap-rating.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<4&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofSeconds(1))){if(!first.ratingId().toString().equals(record.key()))continue;var env=RoadmapRatingEnvelopeV1.parseFrom(record.value());var p=RoadmapRatingChangedV1.parseFrom(env.getPayload());assertArrayEquals(expected.get(env.getEventId()),record.value());assertEquals(space.toString(),env.getSpaceId());assertEquals(actor.toString(),env.getActorId());assertEquals(trace,env.getTraceId());assertEquals("RoadmapRating",env.getAggregateType());assertEquals(1,env.getEventVersion());assertEquals(7,UUID.fromString(p.getRevisionId()).version());assertEquals(1,p.getRoadmapVersion());assertEquals(List.of(4,5,5,2).get((int)p.getVersion()-1).intValue(),p.getScore());assertEquals(p.getVersion()==3?"RETIRED":"ACTIVE",p.getState());for(var pair:Map.of("trace_id",trace,"schema_group","learning","schema_artifact","roadmap-rating-events","schema_version","1").entrySet())assertEquals(pair.getValue(),new String(record.headers().lastHeader(pair.getKey()).value(),StandardCharsets.UTF_8));if(found.add(env.getEventId()))versions.add(p.getVersion());}assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L,3L,4L),versions);}
 }
}
